begin;
create type human_verification_target_type as enum('CLAIM','COMPANY_RESOLUTION','COMPANY_ROLE','PROJECT','MANPOWER_ACCEPTANCE','CONTACT_PERSON','CONTACT_ROUTE','CONTACT_ROUTE_GRADE','OPPORTUNITY_CONFLICT');
create type human_verification_decision as enum('VERIFY','REJECT','NEEDS_MORE_EVIDENCE','DEFER');
create table human_verification_decisions(id uuid primary key default gen_random_uuid(),target_type human_verification_target_type not null,target_id uuid not null,decision human_verification_decision not null,reviewer_id text not null check(length(trim(reviewer_id))>0),reason text not null check(length(trim(reason))>0),decided_at timestamptz not null,previous_state verification_state,resulting_state verification_state,primary_evidence_id uuid references raw_evidence(id) on delete restrict,supersedes_decision_id uuid references human_verification_decisions(id) on delete restrict,rule_version text not null check(length(trim(rule_version))>0),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),check(supersedes_decision_id is null or supersedes_decision_id<>id),check(decision<>'VERIFY' or(primary_evidence_id is not null and resulting_state='VERIFIED')),check(decision<>'REJECT' or resulting_state='REJECTED'),check(decision not in('NEEDS_MORE_EVIDENCE','DEFER') or resulting_state is not distinct from previous_state));
create table human_verification_decision_evidence(decision_id uuid not null references human_verification_decisions(id) on delete restrict,evidence_id uuid not null references raw_evidence(id) on delete restrict,created_at timestamptz not null default now(),primary key(decision_id,evidence_id));
create function prevent_human_verification_mutation()returns trigger language plpgsql as $$begin raise exception '% is append-only',tg_table_name;end;$$;
create trigger human_verification_decisions_append_only before update or delete on human_verification_decisions for each row execute function prevent_human_verification_mutation();
create trigger human_verification_evidence_append_only before update or delete on human_verification_decision_evidence for each row execute function prevent_human_verification_mutation();
create index human_verification_target_history_idx on human_verification_decisions(target_type,target_id,decided_at desc,created_at desc);create index human_verification_reviewer_idx on human_verification_decisions(reviewer_id,decided_at desc);create index human_verification_supersedes_idx on human_verification_decisions(supersedes_decision_id)where supersedes_decision_id is not null;
commit;
